--
-- Name: report_intrastat; Type: VIEW; Schema: public; Owner: odoo
--

CREATE VIEW report_intrastat AS
 SELECT to_char((inv.date_invoice)::timestamp with time zone, 'YYYY'::text) AS name,
    to_char((inv.date_invoice)::timestamp with time zone, 'MM'::text) AS month,
    min(inv_line.id) AS id,
    intrastat.id AS intrastat_id,
    upper((inv_country.code)::text) AS code,
    sum(
        CASE
            WHEN (inv_line.price_unit IS NOT NULL) THEN (inv_line.price_unit * inv_line.quantity)
            ELSE (0)::numeric
        END) AS value,
    sum(
        CASE
            WHEN (uom.category_id <> puom.category_id) THEN (pt.weight * inv_line.quantity)
            ELSE ((pt.weight * inv_line.quantity) * uom.factor)
        END) AS weight,
    sum(
        CASE
            WHEN (uom.category_id <> puom.category_id) THEN inv_line.quantity
            ELSE (inv_line.quantity * uom.factor)
        END) AS supply_units,
    inv.currency_id,
    inv.number AS ref,
        CASE
            WHEN ((inv.type)::text = ANY ((ARRAY['out_invoice'::character varying, 'in_refund'::character varying])::text[])) THEN 'export'::text
            ELSE 'import'::text
        END AS type,
    inv.company_id
   FROM ((((((account_invoice inv
     LEFT JOIN account_invoice_line inv_line ON ((inv_line.invoice_id = inv.id)))
     LEFT JOIN (product_template pt
     LEFT JOIN product_product pp ON ((pp.product_tmpl_id = pt.id))) ON ((inv_line.product_id = pp.id)))
     LEFT JOIN product_uom uom ON ((uom.id = inv_line.uom_id)))
     LEFT JOIN product_uom puom ON ((puom.id = pt.uom_id)))
     LEFT JOIN report_intrastat_code intrastat ON ((pt.intrastat_id = intrastat.id)))
     LEFT JOIN (res_partner inv_address
     LEFT JOIN res_country inv_country ON ((inv_country.id = inv_address.country_id))) ON ((inv_address.id = inv.partner_id)))
  WHERE (((inv.state)::text = ANY ((ARRAY['open'::character varying, 'paid'::character varying])::text[])) AND (inv_line.product_id IS NOT NULL) AND (inv_country.intrastat = true))
  GROUP BY (to_char((inv.date_invoice)::timestamp with time zone, 'YYYY'::text)), (to_char((inv.date_invoice)::timestamp with time zone, 'MM'::text)), intrastat.id, inv.type, pt.intrastat_id, inv_country.code, inv.number, inv.currency_id, inv.company_id;


