_report_views.xml	sale.report.search	primary	sale.report
549	2017-12-08 10:46:37.158345	2017-12-08 10:46:37.158345	1	\N	\N	9182	16	qweb	<?xml version="1.0"?>\n<t t-name="sale.report_saleorder_document">\n    <t t-call="report.external_layout">\n        <t t-set="doc" t-value="doc.with_context({'lang':doc.partner_id.lang})"/>\n        <div class="page">\n            <div class="oe_structure"/>\n            <div class="row">\n                <div class="col-xs-6">\n                    <strong t-if="doc.partner_shipping_id == doc.partner_invoice_id">Invoicing and shipping address:</strong>\n                    <strong t-if="doc.partner_shipping_id != doc.partner_invoice_id">Invoicing address:</strong>\n                    <div t-field="doc.partner_invoice_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;fax&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                    <p t-if="doc.partner_id.vat">VAT: <span t-field="doc.partner_id.vat"/></p>\n                    <div t-if="doc.partner_shipping_id != doc.partner_invoice_id" class="mt8">\n                        <strong>Shipping address:</strong>\n                        <div t-field="doc.partner_shipping_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;fax&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                        <p t-if="doc.partner_id.vat">VAT: <span t-field="doc.partner_id.vat"/></p>\n                    </div>\n                </div>\n                <div class="col-xs-5 col-xs-offset-1">\n                    <div t-field="doc.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>\n                </div>\n            </div>\n\n            <h2>\n                <span t-if="doc.state not in ['draft','sent']">Order # </span>\n                <span t-if="doc.state in ['draft','sent']">Quotation # </span>\n                <span t-field="doc.name"/>\n            </h2>\n\n            <div class="row mt32 mb32" id="informations">\n                <div t-if="doc.client_order_ref" class="col-xs-3">\n                    <strong>Your Reference:</strong>\n                    <p t-field="doc.client_order_ref"/>\n                </div>\n                <div t-if="doc.date_order" class="col-xs-3">\n                    <strong t-if="doc.state not in ['draft','sent']">Date Ordered:</strong>\n                    <strong t-if="doc.state in ['draft','sent']">Quotation Date:</strong>\n                    <p t-field="doc.date_order"/>\n                </div>\n                <div t-if="doc.user_id.name" class="col-xs-3">\n                    <strong>Salesperson:</strong>\n                    <p t-field="doc.user_id"/>\n                </div>\n                <div name="payment_term" t-if="doc.payment_term_id" class="col-xs-3">\n                    <strong>Payment Terms:</strong>\n                    <p t-field="doc.payment_term_id"/>\n                </div>\n            </div>\n\n            <!-- Is there a discount on at least one line? -->\n            <t t-set="display_discount" t-value="any([l.discount for l in doc.order_line])"/>\n\n            <t t-foreach="doc.order_lines_layouted()" t-as="page">\n                <table class="table table-condensed">\n                    <thead>\n                        <tr>\n                            <th>Description</th>\n                            <th class="text-right">Quantity</th>\n                            <th class="text-right">Unit Price</th>\n                            <th t-if="display_discount" class="text-right" groups="sale.group_discount_per_so_line">Disc.(%)</th>\n                            <th class="text-right">Taxes</th>\n                            <th class="text-right" groups="sale.group_show_price_subtotal">Price</th>\n                            <th class="text-right price_tax_included" groups="sale.group_show_price_total">Total Price</th>\n                        </tr>\n                   </thead>\n                   <tbody class="sale_tbody">\n                        <t t-foreach="page" t-as="layout_category">\n\n                            <t t-if="layout_category_size &gt; 1 or page_size &gt; 1" groups="sale.group_sale_layout">\n                                <tr class="active">\n                                    <td colspan="7" style="font-weight: bold; border-bottom: 1px solid black;">&amp;bull;\n                                        <t t-esc="layout_category['name']"/>\n                                    </td>\n                                </tr>\n                            </t>\n\n                            <!-- Lines associated -->\n                            <t t-foreach="layout_category['lines']" t-as="l">\n                                <tr>\n                                    <td><span t-field="l.name"/></td>\n                                    <td class="text-right">\n                                        <span t-field="l.product_uom_qty"/>\n                                        <span t-field="l.product_uom" groups="product.group_uom"/>\n                                    </td>\n                                    <td class="text-right">\n                                        <span t-field="l.price_unit"/>\n                                    </td>\n                                    <td t-if="display_discount" class="text-right" groups="sale.group_discount_per_so_line">\n                                        <span t-field="l.discount"/>\n                                    </td>\n                                    <td class="text-right">\n                                        <span t-esc="', '.join(map(lambda x: (x.description or x.name), l.tax_id))"/>\n                                    </td>\n                                    <td class="text-right" groups="sale.group_show_price_subtotal">\n                                        <span t-field="l.price_subtotal" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: doc.pricelist_id.currency_id}"/>\n                                    </td>\n                                    <td class="text-right" groups="sale.group_show_price_total">\n                                        <span t-field="l.price_total" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: doc.pricelist_id.currency_id}"/>\n                                    </td>\n                                </tr>\n                            </t>\n\n                            <t t-if="(layout_category_size &gt; 1 or page_size &gt; 1) and layout_category['subtotal']" groups="sale.group_sale_layout">\n                                <tr class="text-right">\n                                    <td colspan="6">\n                                        <strong>Subtotal: </strong>\n                                        <t t-set="subtotal" t-value="sum(line.price_subtotal for line in layout_category['lines'])"/>\n                                        <span t-esc="subtotal" t-options="{'widget': 'monetary', 'display_currency': doc.pricelist_id.currency_id}"/>\n                                    </td>\n                                </tr>\n                            </t>\n\n                        </t>\n                    </tbody>\n                </table>\n\n                <t t-if="page_index &lt; page_size - 1" groups="sale.group_sale_layout">\n                    <p style="page-break-before:always;"> </p>\n                </t>\n            </t>\n\n            <div class="row" name="total">\n                <div class="col-xs-4 pull-right">\n                    <table class="table table-condensed">\n                        <tr class="border-black">\n                            <td><strong>Total Without Taxes</strong></td>\n                   